INSERT INTO songs (song_number, title, category, song_text, tune, count, created_at) VALUES 
(2, 'Подивися навкруги на красу землі своєї', 30, 'Куплет 1\nПодивися навкруги, на красу землі своєї.\nВсе це Бог наш сотворив силою руки своєї.\nВін один так полюбив, що віддав нам свого Сина.\nМилість Бог свою явив, щоб спаслася Україна.\n\nПриспів:\nМи молим за свій край,\nСпасіння людям дай.\nМи Тебе благаєм.\n\nКуплет 2\nЛюбов свою яви,\nГосподь, благослови\nНашу Україну.\n\nКуплет 3\nБоже єдності нам дай, навчи любити і прощати.\nВ згоді Господа Христа будем разом прославляти.\nТи один так полюбив, що віддав нам свого Сина.\nМилість нам свою явив, щоб спаслася Україна.', '', 2, '2021-04-11'),
(3, 'Эрусалим що сходить з неба', 0, 'Куплет 1\nЄрусалим, що сходить з неба\nВ проміннях ясних свого Царя,\nТам більше сонця вже не потрібно, \nБо Агнець Божий -  рання зоря.\n\nПрипев\nОце оселя свята Бога з людьми,\nДе будем жити із Богом ми.\nТам усі сльози Ісус з очей зітре.\nСмерті не буде, біль промине.\n\nКуплет 2\nЄрусалим! Нове це місто,\nПерлинні брами відкриті в нім.\nХто прагне пити - нехай приходить, -\nДжерельні води течуть у нім.\n\nКуплет3\nЄрусалим! Тебе кохаю.\nВ тобі панує вічна любов.\nСпасенні люди в тобі зійдуться.\nПрославлять Спаса за  Його кров.', '', 2, '2020-10-30'),
(6, 'ты ждешь когда', 30, 'Куплет 1\nТы ждешь, когда я приду к Тебе\nТакой как есть\n\nПрипев\nПечать Твоей любви в сердце моем\nНавеки и навсегда\nКак велика Твоя любовь\nРевность как летящая стрела\n\nКуплет 2\nПриди огнем Своим, Господь,\nСожги мой грех, омой меня\nПриди огнём Своим, Господь,\nИ будем вместе Ты и я\n\nПрипев\nБольше не хочу говорить я\nИ в ночной темноте\nЛишь смотреть на Тебя хочу,\nТолько петь Тебе.', '', 1, '2021-04-09'),
(7, 'Год прошёл', 0, 'Куплет 1\nГод прошёл и снова собрались друзья,\nСнова добрым словом ободрят меня.\nТак за годом год пройдёт, как лёгкий дым,\nВсё пройдёт, и радость, горе вместе с ним.\n\nПрипев:\nИ тогда вернётся снова весна,\nВсе мы соберёмся у ног Христа.\nИ тогда не будем годы считать,\nИ не будем страдать.\n\nКуплет 2\nСколько дней мы будем радости иметь, \nСколько дней мы будем в горе скорбеть?\nМы не знаем, только будь ты со Христом \nИ борись всегда, всегда борись со злом.\n\nКуплет 3\nСколько зла на свете, но ты добрым будь, \nЛюдям приноси добра хотя чуть-чуть. \nРасцветут прекрасны на пути цветы \nИ расскажут нам о радости они.', '', 0, NULL),
(8, 'Под бичём кровавого удара', 30, 'Куплет 1\nПод бичём кровавого удара,\nНа плечах со взваленным крестом, \nШёл в толпе, тернистый путь свершая, \nЖизнедатель, Пастырь и Господь.\n\nКуплет 2\nПод крестом Он, весь изнемогая \nОт толчков, на землю падал Он,\nПо земле, святую кровь роняя, \nI был поднят бичём, и снова шёл.\n\nКуплет 3\nНо толпа страданьям не внимала,\nТолько Мать, скорбящая душой, \nШла за Ним и слёзы проливала,  \nРоковой подавлена тоской.\n\nКуплет 4\nТак тяжёлый путь свой совершая, \nТяжкий крест Он на Голгофу нёс.\nИ на нём Он умер там, страдая, \nДля того, чтоб грешник был спасен', '', 1, '2020-11-15'),
(11, 'Дивный Спаситель прекрасный', 30, 'Куплет 1\nДивный Спаситель, прекрасный,\nНаш Искупитель и Друг.\nКто мог подумать, что Агнец\nМог искупить нас от мук,\nМог искупить нас от мук?\n\nКуплет 2\nСторож души и Советник,\nДух Твой мы жаждем вдохнуть.\nНовой надеждой Ты светишь,\nЕсли теряем мы путь,\nЕсли теряем мы путь.\n\nПриспів\n// Ты – Тот, Кого прославляем,\nТот, Кого любим всегда.\nДай исцеление и милость\nНашим голодным сердцам,\nНашим голодным сердцам. // - 2р.\n\nКуплет 3\nВечный Отец Всемогущий,\nВерно Ты любишь Своих,\nВ слабости к Трону идущих,\nЧтобы у ног пасть Твоих,\nЧтобы у ног пасть Твоих.', '', 0, NULL),
(12, 'А нас манят ', 0, 'Verse 1\nМеня манят к себе небеса, от земного хочу оторваться. \nЛишь не легкой бы быть на весах, чтоб навеки во тьме не остаться.\nЖизнь должна добродетельной быть, доброй кроткой смирёной и верной.  \nМы должны всеx прощать и любить, не смотря на гоненья и терни. \n\nПрипев:\nА нас манят к себе небеса мы хотим от земли оторваться\nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\nА нас манят к себе небеса мы хотим от земли оторваться\nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\n\nVerse 2 куплет:\nКак легко о делах говорить, но а в жизнь воплотить их не просто,\nДай нам Боже для ближнего жить, дай нам сил для духовного роста.\nЗабываем порой небеса, суета завладеет сознаньем.\nО открой нам спаситель глаза, и наполни ты их покаяньем.\n\nПрипев:\nА нас манят к себе небеса мы хотим от земли оторваться \nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\nА нас манят к себе небеса мы хотим от земли оторваться     \nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\n\nVerse 3 дополнительный\nПоднимите глаза в небеса, в небе дом наш и наша отчизна,\nВ своём сердце Христу дверь открыв, навсегда чтобы Он в нём поселился.\nПтицы стаями в небо летят, доверяясь во всём лишь на жатву.\nНам пример они свой оставляют, доверятся во всём только Богу.', '', 0, NULL),
(14, 'Дух Святой, дорогой Как глубока Твоя любовь', 0, 'Verse 1\nКак глубока Твоя любовь, и прощение наш покров.\nТы наш свет и наш покой, упование, Бог Святой.\n\nVerse2\nТвоя милость велика, Твоя правда высока,\nТвоя сильная рука нас ведет издалека.\n\nRefrain 1\nДух Святой, дорогой, драгоценный Дух Святой,\nНаполняй сердца славою Отца.\nДух Святой, дорогой, драгоценный Дух Святой,\nОсвящай и веди за Собой.\n\nVerse 1\nО сколько раз я был во мгле но рука Твоя была со мной\nВ долине скорби на земле ничего не боюсь я с Тобой', '', 1, '2020-10-23'),
(15, ' Кров Христа за мене У стражданнях і тузі', 0, 'Verse 1\nУ стражданнях і тузі наш Господь був на хресті,\nВін поніс туди всі болі і гріхи.\nВін – Предвічний і Святий всіх людей так полюбив,\nСвою кров за всіх людей Він проливав.\n\nПриспів:\nЗнаєш Кров Христа за мене теж лилась,\nКров Христа захистить моє  життя!\nКров Христа – омиває від гріха,\nСила, що рятує нас – кров Христа, кров Христа!\n\nVerse 2\nІ немов мале Ягня, став Він жертвою за нас,\nЙого кров з хреста лилася за людей.\nКров змиває всі гріхи і рятує від діл тьми,\nКожен день, в молитві, кличу до Христа!', '', 1, '2020-10-25'),
(16, 'Ісусе Ти Спас мій Богові слава', 0, 'Куплет 1\nІсусе, Ти – Спас мій, немає  такого, як Ти,\nВсі  дні мої тут на землі хочу прославлять Тебе.\nПритулок, твердиня, захист від лиха та зла\nЯ буду співать, Тебе прославлять,\nПоки буду жити на землі.\n\nКуплет 2\nБогові слава! Вся земле, співай,\nЧесть і хвалу ти для Бога віддай,\nВклоняються гори, шумить водопад\nНад іменням дивним Твоїм.\nРадісну пісню співаю Тобі,\nНавіки прославлю, навіки я Твій,\nНемає на світі того, що я маю в Тобі!', '', 6, '2021-03-21'),
(17, 'Я дякую Тобі', 0, 'Verse 1\nЯ дякую Тобі мій Бог за очі,\nЯкими бачу все, що Ти створив.\nЯ знаю тих, для кого дні як ночі,\nХто бачить сонце тільки в хвилях снів.\n\nVerse 2\nЯ дякую тобі мій Бог за руки,\nЯкими можу я тримати хліб,\nВтирать сльозу в печальний час розлуки,\nІ працювати можу на землі.\n\nRefrain 3\nЯ дякую Тобі, я дякую Тобі,\nПрийми Господь подяку,\nЯ радуюсь в Тобі, я радуюсь в Тобі,\nПрийми Господь подяку.\n\nVerse 4\nЯ дякую Тобі, мій Бог, за маму\nЗа мирне небо, світлі почуття,\nНавчи нас Боже щирими устами\nТебе хвалити все своє життя.\n\nVerse 5\nЯ дякую Тобі мій Бог за очі,\nЯкими бачу все, що Ти створив.\nХвалити прагну, дякувати хочу,\nА Ти до мого серця говори.', '', 4, '2020-11-08'),
(18, 'Нехай Бог Благословить  І помилує тебе', 0, 'Verse 1\nНехай Бог Благословить \nТебе і береже\nХай оберне на тебе Господь\nСвітле лице своє\n\nRefrain\nІ помилує тебе\nПоверне Господь лице своє\nНа тебе і дасть тобі\nСвій мир.\n\nVerse 2\nХай благословить, тебе Господь\nІ дасть тобі Свій мир.', '', 4, '2021-04-04');